SELECT cr.*, c.coursename, t.teachername
FROM course_resource cr
LEFT JOIN course c ON cr.courseid = c.courseid
LEFT JOIN teacher t ON cr.teacherid = t.teacherid
WHERE c.teacherid = #{teacherid}

    AND cr.title LIKE CONCAT('%', #{keyword}, '%')


    AND c.semester = #{semester}


    AND cr.courseid = #{courseid}

ORDER BY cr.createtime DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM course_resource cr
LEFT JOIN course c ON cr.courseid = c.courseid
WHERE c.teacherid = #{teacherid}

    AND cr.title LIKE CONCAT('%', #{keyword}, '%')


    AND c.semester = #{semester}


    AND cr.courseid = #{courseid}

